import { Context, Effect, Redacted, Schema } from "effect";

import { CodexOAuthProfileCipherError } from "./errors.js";
import type { CodexOAuthProfileCipherFailure } from "./errors.js";
import { CodexOAuthProfileCipherConfigService } from "./profile-cipher.config.js";
import {
  CodexOAuthCredentialRevision,
  CodexOAuthProfile,
  CodexOAuthProfileCipherKeyId,
  EncryptedCodexOAuthProfileV2,
  LegacyCodexOAuthProfileV1,
} from "./schemas.js";
import type {
  CodexAccessTokenImportProfile as CodexAccessTokenImportProfileType,
  CodexOAuthProfile as CodexOAuthProfileType,
  EncryptedCodexOAuthProfile,
  EncryptedCodexOAuthProfileV2 as EncryptedCodexOAuthProfileV2Type,
  LegacyCodexOAuthProfileV1 as LegacyCodexOAuthProfileV1Type,
} from "./schemas.js";
import { codexOAuthProfileSubjectHash } from "./storage-keys.js";

const codexOAuthProfileJson = Schema.fromJsonString(CodexOAuthProfile);
const legacyCodexOAuthProfileJson = Schema.fromJsonString(
  LegacyCodexOAuthProfileV1
);

const toArrayBuffer = (value: Uint8Array) => {
  const copy = new Uint8Array(value.byteLength);
  copy.set(value);
  return copy.buffer;
};

const migrateLegacyCodexOAuthProfile = (
  profile: LegacyCodexOAuthProfileV1Type
): CodexAccessTokenImportProfileType => ({
  profileVersion: 2,
  profileKind: "access-token-import",
  subject: profile.subject,
  accessToken: profile.accessToken,
  expiresAtEpochMillis: profile.expiresAtEpochMillis,
  scopes: profile.scopes,
  createdAtEpochMillis: profile.createdAtEpochMillis,
  updatedAtEpochMillis: profile.updatedAtEpochMillis,
  requiresReauthentication: profile.requiresReauthentication,
});

export interface CodexOAuthProfileCipherShape {
  readonly encrypt: (
    profile: CodexOAuthProfileType
  ) => Effect.Effect<
    EncryptedCodexOAuthProfileV2Type,
    CodexOAuthProfileCipherFailure
  >;
  readonly decrypt: (
    encryptedProfile: EncryptedCodexOAuthProfile
  ) => Effect.Effect<CodexOAuthProfileType, CodexOAuthProfileCipherFailure>;
}

export class CodexOAuthProfileCipher extends Context.Service<
  CodexOAuthProfileCipher,
  CodexOAuthProfileCipherShape
>()("@bundjil/codex-oauth/CodexOAuthProfileCipher") {}

export const makeCodexOAuthProfileCipher = Effect.fn(
  "CodexOAuthProfileCipherLive"
)(function* makeCodexOAuthProfileCipherService(
  crypto: Crypto = globalThis.crypto
) {
  const config = yield* CodexOAuthProfileCipherConfigService;
  const keyMaterial = yield* Schema.decodeUnknownEffect(
    Schema.Uint8ArrayFromBase64
  )(Redacted.value(config.keyMaterial)).pipe(
    Effect.mapError(
      () =>
        new CodexOAuthProfileCipherError({
          operation: "loadKey",
          keyId: config.keyId,
          message: "Codex OAuth profile encryption key material is invalid.",
        })
    )
  );
  const key = yield* Effect.tryPromise({
    try: () =>
      crypto.subtle.importKey(
        "raw",
        toArrayBuffer(keyMaterial),
        config.algorithm,
        false,
        ["encrypt", "decrypt"]
      ),
    catch: () =>
      new CodexOAuthProfileCipherError({
        operation: "loadKey",
        keyId: config.keyId,
        message: "Unable to import the Codex OAuth profile encryption key.",
      }),
  });

  return CodexOAuthProfileCipher.of({
    encrypt: Effect.fn("CodexOAuthProfileCipher.encrypt")(function* (
      profile: CodexOAuthProfileType
    ) {
      const subjectHash = yield* codexOAuthProfileSubjectHash(
        profile.subject
      ).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encrypt",
              keyId: config.keyId,
              message: "Unable to derive the encrypted profile subject hash.",
            })
        )
      );
      const plaintext = yield* Schema.encodeEffect(codexOAuthProfileJson)(
        profile
      ).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encode",
              keyId: config.keyId,
              message:
                "Unable to encode the Codex OAuth profile for encryption.",
            })
        )
      );
      const nonce = yield* Effect.try({
        try: () => crypto.getRandomValues(new Uint8Array(12)),
        catch: () =>
          new CodexOAuthProfileCipherError({
            operation: "encrypt",
            keyId: config.keyId,
            message: "Unable to generate a profile encryption nonce.",
          }),
      });
      const ciphertext = yield* Effect.tryPromise({
        try: () =>
          crypto.subtle.encrypt(
            {
              name: config.algorithm,
              iv: toArrayBuffer(nonce),
              tagLength: 128,
            },
            key,
            new TextEncoder().encode(plaintext)
          ),
        catch: () =>
          new CodexOAuthProfileCipherError({
            operation: "encrypt",
            keyId: config.keyId,
            message: "Unable to encrypt the Codex OAuth profile.",
          }),
      });

      return yield* Schema.decodeUnknownEffect(EncryptedCodexOAuthProfileV2)({
        version: 2,
        algorithm: config.algorithm,
        keyId: config.keyId,
        nonce,
        ciphertext: new Uint8Array(ciphertext),
        subjectHash,
        createdAtEpochMillis: profile.createdAtEpochMillis,
        updatedAtEpochMillis: profile.updatedAtEpochMillis,
      }).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "encode",
              keyId: config.keyId,
              message: "Unable to encode the encrypted Codex OAuth profile.",
            })
        )
      );
    }),
    decrypt: Effect.fn("CodexOAuthProfileCipher.decrypt")(function* (
      encryptedProfile: EncryptedCodexOAuthProfile
    ) {
      if (encryptedProfile.version !== 1 && encryptedProfile.version !== 2) {
        return yield* new CodexOAuthProfileCipherError({
          operation: "unsupportedVersion",
          keyId: encryptedProfile.keyId,
          version: encryptedProfile.version,
          message: "The encrypted Codex OAuth profile version is unsupported.",
        });
      }

      if (encryptedProfile.keyId !== config.keyId) {
        return yield* new CodexOAuthProfileCipherError({
          operation: "keyMismatch",
          keyId: encryptedProfile.keyId,
          version: encryptedProfile.version,
          message:
            "The encrypted Codex OAuth profile was encrypted with another key.",
        });
      }

      const plaintext = yield* Effect.tryPromise({
        try: () =>
          crypto.subtle.decrypt(
            {
              name: encryptedProfile.algorithm,
              iv: toArrayBuffer(encryptedProfile.nonce),
              tagLength: 128,
            },
            key,
            toArrayBuffer(encryptedProfile.ciphertext)
          ),
        catch: () =>
          new CodexOAuthProfileCipherError({
            operation: "decrypt",
            keyId: encryptedProfile.keyId,
            version: encryptedProfile.version,
            message: "Unable to decrypt the Codex OAuth profile.",
          }),
      });
      const profile = yield* Effect.gen(function* decodeProfile() {
        const plaintextJson = new TextDecoder().decode(plaintext);

        if (encryptedProfile.version === 2) {
          return yield* Schema.decodeUnknownEffect(codexOAuthProfileJson)(
            plaintextJson
          ).pipe(
            Effect.mapError(
              () =>
                new CodexOAuthProfileCipherError({
                  operation: "decode",
                  keyId: encryptedProfile.keyId,
                  version: encryptedProfile.version,
                  message:
                    "Unable to decode the decrypted Codex OAuth profile.",
                })
            )
          );
        }

        const legacyProfile = yield* Schema.decodeUnknownEffect(
          legacyCodexOAuthProfileJson
        )(plaintextJson).pipe(
          Effect.mapError(
            () =>
              new CodexOAuthProfileCipherError({
                operation: "decode",
                keyId: encryptedProfile.keyId,
                version: encryptedProfile.version,
                message:
                  "Unable to decode the legacy decrypted Codex OAuth profile.",
              })
          )
        );

        return migrateLegacyCodexOAuthProfile(legacyProfile);
      });
      const subjectHash = yield* codexOAuthProfileSubjectHash(
        profile.subject
      ).pipe(
        Effect.mapError(
          () =>
            new CodexOAuthProfileCipherError({
              operation: "integrityMismatch",
              keyId: encryptedProfile.keyId,
              version: encryptedProfile.version,
              message:
                "Unable to verify the encrypted Codex OAuth profile subject.",
            })
        )
      );

      if (subjectHash !== encryptedProfile.subjectHash) {
        return yield* new CodexOAuthProfileCipherError({
          operation: "integrityMismatch",
          keyId: encryptedProfile.keyId,
          version: encryptedProfile.version,
          message: "The encrypted Codex OAuth profile subject does not match.",
        });
      }

      return profile;
    }),
  });
});

export const encryptCodexOAuthProfile = (profile: CodexOAuthProfileType) =>
  Effect.gen(function* encryptCodexOAuthProfileOperation() {
    const cipher = yield* CodexOAuthProfileCipher;

    return yield* cipher.encrypt(profile);
  });

export const decryptCodexOAuthProfile = (
  encryptedProfile: EncryptedCodexOAuthProfile
) =>
  Effect.gen(function* decryptCodexOAuthProfileOperation() {
    const cipher = yield* CodexOAuthProfileCipher;

    return yield* cipher.decrypt(encryptedProfile);
  });

export const generateCodexOAuthCredentialRevision = Effect.fn(
  "CodexOAuthCredentialRevision.generate"
)(function* generateCodexOAuthCredentialRevisionOperation() {
  const generatedKeyId = yield* Schema.decodeUnknownEffect(
    CodexOAuthProfileCipherKeyId
  )("generated").pipe(
    Effect.mapError(
      () =>
        new CodexOAuthProfileCipherError({
          operation: "encode",
          message: "Unable to generate a Codex OAuth credential revision.",
        })
    )
  );

  return yield* Schema.decodeUnknownEffect(CodexOAuthCredentialRevision)(
    globalThis.crypto.randomUUID()
  ).pipe(
    Effect.mapError(
      () =>
        new CodexOAuthProfileCipherError({
          operation: "encode",
          keyId: generatedKeyId,
          message: "Unable to generate a Codex OAuth credential revision.",
        })
    )
  );
});
import { Context, Effect } from "effect";

import { CodexHttpNetworkError } from "./errors.js";

export interface CodexResponsesFetchShape {
  readonly fetch: (
    request: Request
  ) => Effect.Effect<Response, CodexHttpNetworkError>;
}

export class CodexResponsesFetch extends Context.Service<
  CodexResponsesFetch,
  CodexResponsesFetchShape
>()("@bundjil/codex-oauth/CodexResponsesFetch") {}

export const makeCodexResponsesFetch = CodexResponsesFetch.of({
  fetch: Effect.fn("CodexResponsesFetch.fetch")((request: Request) =>
    Effect.tryPromise({
      try: () => globalThis.fetch(request),
      catch: (cause) =>
        new CodexHttpNetworkError({
          operation: "fetch",
          message: "Unable to reach Codex Responses endpoint.",
          cause,
        }),
    })
  ),
});
import {
  Context,
  Effect,
  HashMap,
  Match,
  Option,
  Redacted,
  Schema,
} from "effect";

import { CodexResponsesStreamError } from "./errors.js";
import {
  CodexResponsesFunctionArgumentsDeltaEvent,
  CodexResponsesFunctionCallAddedEvent,
  CodexResponsesOutputItemDiscriminator,
  CodexResponsesRecognizedStreamEventType,
  CodexResponsesStreamEvent,
  OpenAICompatibleChatCompletionChunk,
  OpenAICompatibleChatCompletionId,
  OpenAICompatibleChatCompletionStream,
} from "./schemas.js";
import type {
  CodexResponsesStreamMapInput,
  OpenAICompatibleChatCompletionChunk as OpenAICompatibleChatCompletionChunkType,
  OpenAICompatibleChatCompletionStream as OpenAICompatibleChatCompletionStreamType,
} from "./schemas.js";

export interface CodexStreamMapperShape {
  readonly toOpenAICompatibleStream: (
    input: CodexResponsesStreamMapInput
  ) => Effect.Effect<
    OpenAICompatibleChatCompletionStreamType,
    CodexResponsesStreamError
  >;
}

export class CodexStreamMapper extends Context.Service<
  CodexStreamMapper,
  CodexStreamMapperShape
>()("@bundjil/codex-oauth/CodexStreamMapper") {}

const decodeCodexStreamLine = (line: string) => {
  const data = line.startsWith("data: ") ? line.slice("data: ".length) : "";

  if (data.length === 0 || data === "[DONE]") {
    return Effect.succeed(Option.none<typeof CodexResponsesStreamEvent.Type>());
  }

  return Schema.decodeUnknownEffect(
    Schema.fromJsonString(CodexResponsesStreamEvent)
  )(data).pipe(
    Effect.map(Option.some),
    Effect.mapError(
      (cause) =>
        new CodexResponsesStreamError({
          operation: "toOpenAICompatibleStream",
          message: "Unable to decode Codex Responses stream event.",
          cause,
        })
    )
  );
};

export const makeCodexStreamMapper = CodexStreamMapper.of({
  toOpenAICompatibleStream: Effect.fn(
    "CodexStreamMapper.toOpenAICompatibleStream"
  )(function* (input: CodexResponsesStreamMapInput) {
    const decodedEvents = yield* Effect.forEach(
      Redacted.value(input.body)
        .split(/\r?\n/)
        .filter((line) => line.trim().length > 0),
      decodeCodexStreamLine
    );
    const completionId = yield* Schema.decodeUnknownEffect(
      OpenAICompatibleChatCompletionId
    )("bundjil-codex").pipe(
      Effect.mapError(
        (cause) =>
          new CodexResponsesStreamError({
            operation: "toOpenAICompatibleStream",
            message: "Unable to construct OpenAI-compatible completion ID.",
            cause,
          })
      )
    );
    const chunks: OpenAICompatibleChatCompletionChunkType[] = [];
    let functionCallIndexes = HashMap.empty<number, number>();
    let nextFunctionCallIndex = 0;
    let hasFunctionCall = false;

    yield* Effect.all(
      decodedEvents.map((decodedEvent) =>
        Effect.gen(function* mapCodexStreamEvent() {
          if (Option.isNone(decodedEvent)) {
            return yield* Effect.void;
          }

          const event = decodedEvent.value;

          const recognizedEventType = yield* Schema.decodeUnknownEffect(
            CodexResponsesRecognizedStreamEventType
          )(event.type).pipe(Effect.option);
          return yield* Option.match(recognizedEventType, {
            onNone: () => Effect.void,
            onSome: (eventType) =>
              Match.value(eventType).pipe(
                Match.when("response.output_text.delta", () =>
                  event.delta === undefined
                    ? Effect.void
                    : Effect.sync(() => {
                        chunks.push({
                          id: completionId,
                          object: "chat.completion.chunk",
                          created: 0,
                          model: input.model,
                          choices: [
                            {
                              index: 0,
                              delta: { content: event.delta },
                              finish_reason: null,
                            },
                          ],
                        });
                      })
                ),
                Match.when("response.output_item.added", () =>
                  Effect.gen(function* mapFunctionCallOutputItem() {
                    const item = yield* Schema.decodeUnknownEffect(
                      CodexResponsesOutputItemDiscriminator
                    )(event.item).pipe(
                      Effect.mapError(
                        (cause) =>
                          new CodexResponsesStreamError({
                            operation: "toOpenAICompatibleStream",
                            message:
                              "Unable to decode Codex Responses output item.",
                            cause,
                          })
                      )
                    );

                    return yield* Match.value(item.type).pipe(
                      Match.when("function_call", () =>
                        Effect.gen(function* mapFunctionCall() {
                          const functionCall =
                            yield* Schema.decodeUnknownEffect(
                              CodexResponsesFunctionCallAddedEvent
                            )(event).pipe(
                              Effect.mapError(
                                (cause) =>
                                  new CodexResponsesStreamError({
                                    operation: "toOpenAICompatibleStream",
                                    message:
                                      "Unable to decode Codex function-call output item.",
                                    cause,
                                  })
                              )
                            );
                          hasFunctionCall = true;
                          const functionCallIndex = nextFunctionCallIndex;
                          functionCallIndexes = HashMap.set(
                            functionCallIndexes,
                            functionCall.output_index,
                            functionCallIndex
                          );
                          nextFunctionCallIndex += 1;
                          chunks.push({
                            id: completionId,
                            object: "chat.completion.chunk",
                            created: 0,
                            model: input.model,
                            choices: [
                              {
                                index: 0,
                                delta: {
                                  tool_calls: [
                                    {
                                      index: functionCallIndex,
                                      id: functionCall.item.call_id,
                                      type: "function",
                                      function: {
                                        name: functionCall.item.name,
                                        arguments: functionCall.item.arguments,
                                      },
                                    },
                                  ],
                                },
                                finish_reason: null,
                              },
                            ],
                          });
                        })
                      ),
                      Match.orElse(() => Effect.void)
                    );
                  })
                ),
                Match.when("response.function_call_arguments.delta", () =>
                  Effect.gen(function* mapFunctionCallArguments() {
                    const functionArguments = yield* Schema.decodeUnknownEffect(
                      CodexResponsesFunctionArgumentsDeltaEvent
                    )(event).pipe(
                      Effect.mapError(
                        (cause) =>
                          new CodexResponsesStreamError({
                            operation: "toOpenAICompatibleStream",
                            message:
                              "Unable to decode Codex function-call arguments.",
                            cause,
                          })
                      )
                    );
                    const functionCallIndex = HashMap.get(
                      functionCallIndexes,
                      functionArguments.output_index
                    );

                    if (Option.isNone(functionCallIndex)) {
                      return yield* new CodexResponsesStreamError({
                        operation: "toOpenAICompatibleStream",
                        message:
                          "Codex function-call arguments arrived before their output item.",
                        cause: "Missing function-call output index.",
                      });
                    }

                    hasFunctionCall = true;
                    chunks.push({
                      id: completionId,
                      object: "chat.completion.chunk",
                      created: 0,
                      model: input.model,
                      choices: [
                        {
                          index: 0,
                          delta: {
                            tool_calls: [
                              {
                                index: functionCallIndex.value,
                                function: {
                                  arguments: functionArguments.delta,
                                },
                              },
                            ],
                          },
                          finish_reason: null,
                        },
                      ],
                    });
                    return yield* Effect.void;
                  })
                ),
                Match.exhaustive
              ),
          });
        })
      ),
      { concurrency: 1 }
    );

    chunks.push({
      id: completionId,
      object: "chat.completion.chunk",
      created: 0,
      model: input.model,
      choices: [
        {
          index: 0,
          delta: {},
          finish_reason: hasFunctionCall ? "tool_calls" : "stop",
        },
      ],
    });

    const encodedChunks = yield* Effect.all(
      chunks.map((chunk) =>
        Schema.encodeEffect(
          Schema.fromJsonString(OpenAICompatibleChatCompletionChunk)
        )(chunk).pipe(
          Effect.mapError(
            (cause) =>
              new CodexResponsesStreamError({
                operation: "toOpenAICompatibleStream",
                message: "Unable to encode OpenAI-compatible stream chunk.",
                cause,
              })
          )
        )
      )
    );

    const body = `${encodedChunks
      .map((chunk) => `data: ${chunk}\n\n`)
      .join("")}data: [DONE]\n\n`;

    return yield* Schema.decodeUnknownEffect(
      OpenAICompatibleChatCompletionStream
    )({
      contentType: "text/event-stream",
      body,
    }).pipe(
      Effect.mapError(
        (cause) =>
          new CodexResponsesStreamError({
            operation: "toOpenAICompatibleStream",
            message: "Unable to decode OpenAI-compatible stream result.",
            cause,
          })
      )
    );
  }),
